import sys, os

def fix_model_dir(model_dir):
    # Fix modeling_prismatic.py: tie_weights signature
    mp = os.path.join(model_dir, 'modeling_prismatic.py')
    if os.path.exists(mp):
        content = open(mp).read()
        if 'def tie_weights(self) -> None:' in content:
            content = content.replace(
                'def tie_weights(self) -> None:',
                'def tie_weights(self, **kwargs) -> None:'
            )
            open(mp, 'w').write(content)
            print(f'  Fixed tie_weights in {mp}')
        else:
            print(f'  tie_weights already fixed in {mp}')

    # Fix processing_prismatic.py: import locations
    pp = os.path.join(model_dir, 'processing_prismatic.py')
    if os.path.exists(pp):
        content = open(pp).read()
        old_import = 'from transformers.tokenization_utils import PaddingStrategy, PreTokenizedInput, TextInput, TruncationStrategy'
        new_import = 'from transformers.utils import PaddingStrategy\nfrom transformers.tokenization_utils_base import PreTokenizedInput, TextInput, TruncationStrategy'
        if old_import in content:
            content = content.replace(old_import, new_import)
            open(pp, 'w').write(content)
            print(f'  Fixed imports in {pp}')
        else:
            print(f'  Imports already fixed in {pp}')

for d in sys.argv[1:]:
    print(f'Fixing {d}...')
    if os.path.isdir(d):
        fix_model_dir(d)
    else:
        print(f'  Directory not found, skipping')

